"""Oracle tests for the Diebold-Mariano test.

statsmodels has no ``diebold_mariano_test`` (checked in 0.15), so the references are:

* statsmodels' HAC covariance (``sandwich_covariance.cov_hac``) for the long-run variance,
  with the uniform kernel (Diebold & Mariano's truncated estimator) and the Bartlett kernel;
* a literal transcription of the algorithm of R's ``forecast::dm.test`` (autocovariances
  from ``acf(type = "covariance")``, divided by T) written with explicit loops;
* stored ``forecast::dm.test`` output, when ``fixtures/dm_r.json`` has been generated by
  ``fixtures/make_dm_fixtures.R`` (R is not available in every environment).
"""

import json
from pathlib import Path

import numpy as np
import pytest
import statsmodels.api as sm
import statsmodels.stats.sandwich_covariance as sw
from scipy import stats

from isbetter.methods.forecasting import (
    diebold_mariano,
    hln_factor,
    long_run_variance,
    naive_dm_t,
)

FIXTURE = Path(__file__).parent / "fixtures" / "dm_r.json"


def ma_errors(rng, T, h, scale=1.0):
    """h-step forecast errors: sums of h consecutive shocks, an MA(h - 1) process."""
    eps = rng.standard_normal(T + h - 1)
    return scale * np.convolve(eps, np.ones(h), mode="valid")


def r_dm_test(e1, e2, h, power):
    """Transcription of forecast::dm.test (varestimator = "acf", two-sided, default)."""
    n = len(e1)
    d = [abs(a) ** power - abs(b) ** power for a, b in zip(e1, e2, strict=True)]
    dbar = sum(d) / n
    gamma = []
    for lag in range(h):
        s = 0.0
        for t in range(lag, n):
            s += (d[t] - dbar) * (d[t - lag] - dbar)
        gamma.append(s / n)
    var = (gamma[0] + 2 * sum(gamma[1:])) / n
    stat = dbar / var**0.5
    k = ((n + 1 - 2 * h + (h / n) * (h - 1)) / n) ** 0.5
    stat *= k
    p = 2 * stats.t.sf(abs(stat), n - 1)
    return stat, p


@pytest.mark.parametrize("h", [1, 3, 7])
@pytest.mark.parametrize("T", [25, 60, 300])
@pytest.mark.parametrize("power", [1, 2])
def test_matches_dm_test_transcription(h, T, power):
    rng = np.random.default_rng(1000 * h + T + power)
    e1, e2 = ma_errors(rng, T, h), ma_errors(rng, T, h, 1.2)
    la, lb = np.abs(e1) ** power, np.abs(e2) ** power
    stat, p = r_dm_test(e1, e2, h, power)
    r = diebold_mariano(la, lb, horizon=h)
    assert r.statistic == pytest.approx(stat, rel=1e-10, abs=1e-12)
    assert r.p_value == pytest.approx(p, rel=1e-9, abs=1e-14)
    assert r.df == T - 1


@pytest.mark.parametrize("h", [1, 3, 7])
def test_long_run_variance_matches_statsmodels_hac(h):
    rng = np.random.default_rng(h)
    T = 80
    d = ma_errors(rng, T, h) ** 2 - ma_errors(rng, T, h, 1.1) ** 2
    res = sm.OLS(d, np.ones(T)).fit()
    for kernel, weights in (("rectangular", sw.weights_uniform), ("bartlett", sw.weights_bartlett)):
        ref = sw.cov_hac(res, nlags=h - 1, weights_func=weights, use_correction=False)[0, 0]
        assert long_run_variance(d, h - 1, kernel) / T == pytest.approx(ref, rel=1e-10)


@pytest.mark.parametrize("h", [1, 3, 7])
def test_bartlett_se_matches_statsmodels_ols_hac(h):
    """The Newey-West route (hac_lags) reproduces OLS-on-a-constant HAC standard errors."""
    rng = np.random.default_rng(10 + h)
    T = 120
    la, lb = ma_errors(rng, T, h) ** 2, ma_errors(rng, T, h, 1.1) ** 2
    d = la - lb
    fit = sm.OLS(d, np.ones(T)).fit(
        cov_type="HAC", cov_kwds={"maxlags": h - 1, "use_correction": False}
    )
    r = diebold_mariano(la, lb, horizon=h, hln=False, hac_lags=h - 1)
    assert r.estimate == pytest.approx(float(fit.params[0]), abs=1e-12)
    assert r.diagnostics["se"] == pytest.approx(float(fit.bse[0]), rel=1e-10)
    assert r.statistic == pytest.approx(float(fit.tvalues[0]), rel=1e-10)


def test_hand_computed_h2_example():
    # d = L_a - L_b with L_b = 0: d = [1, 3, 2, 4, 5]; mean 3; centred [-2, 0, -1, 1, 2]
    # gamma_0 = (4+0+1+1+4)/5 = 2; gamma_1 = ((-2*0)+(0*-1)+(-1*1)+(1*2))/5 = 0.2
    # LRV = 2 + 2*0.2 = 2.4; se = sqrt(2.4/5); HLN factor = sqrt((5+1-4+2/5)/5)
    la, lb = np.array([1.0, 3.0, 2.0, 4.0, 5.0]), np.zeros(5)
    r = diebold_mariano(la, lb, horizon=2)
    dm = 3.0 / np.sqrt(2.4 / 5)
    k = np.sqrt((5 + 1 - 4 + 2 / 5) / 5)
    assert r.diagnostics["long_run_variance"] == pytest.approx(2.4, abs=1e-12)
    assert r.diagnostics["dm_statistic"] == pytest.approx(dm, abs=1e-12)
    assert hln_factor(5, 2) == pytest.approx(k, abs=1e-12)
    assert r.statistic == pytest.approx(k * dm, abs=1e-12)
    assert r.p_value == pytest.approx(2 * stats.t.sf(k * dm, 4), abs=1e-12)
    crit = stats.t.ppf(0.975, 4)
    assert r.ci_high - r.estimate == pytest.approx(crit * np.sqrt(2.4 / 5) / k, abs=1e-12)


def test_ci_is_the_inverted_test():
    rng = np.random.default_rng(5)
    la, lb = ma_errors(rng, 90, 3) ** 2, ma_errors(rng, 90, 3, 1.1) ** 2
    r = diebold_mariano(la, lb, horizon=3, alpha=0.1)
    # shifting loss_a by the CI bound makes the test borderline at that alpha
    for bound in (r.ci_low, r.ci_high):
        shifted = diebold_mariano(la - bound, lb, horizon=3, alpha=0.1)
        assert shifted.p_value == pytest.approx(0.1, rel=1e-8)


def test_h1_without_hln_correction_is_normal_z_test_of_paired_differences():
    rng = np.random.default_rng(6)
    la, lb = rng.standard_normal(200) ** 2, rng.standard_normal(200) ** 2 * 1.1
    r = diebold_mariano(la, lb, horizon=1, hln=False)
    d = la - lb
    z = d.mean() / (d.var(ddof=0) / len(d)) ** 0.5
    assert r.statistic == pytest.approx(z, rel=1e-12)
    assert r.p_value == pytest.approx(2 * stats.norm.sf(abs(z)), rel=1e-12)


def test_naive_equals_scipy_paired_ttest():
    rng = np.random.default_rng(7)
    la, lb = rng.standard_normal(70) ** 2, rng.standard_normal(70) ** 2 * 1.2
    r = naive_dm_t(la, lb)
    ref = stats.ttest_rel(la, lb)
    assert r.statistic == pytest.approx(ref.statistic, abs=1e-10)
    assert r.p_value == pytest.approx(ref.pvalue, abs=1e-10)


@pytest.mark.skipif(not FIXTURE.exists(), reason="run fixtures/make_dm_fixtures.R to generate")
def test_matches_r_forecast_dm_test():
    fixture = json.loads(FIXTURE.read_text())
    assert fixture["cases"]
    for case in fixture["cases"]:
        e1, e2 = np.array(case["e1"]), np.array(case["e2"])
        r = diebold_mariano(np.abs(e1) ** case["power"], np.abs(e2) ** case["power"], case["h"])
        assert r.statistic == pytest.approx(case["statistic"], rel=1e-8)
        assert r.p_value == pytest.approx(case["p_value"], rel=1e-7)
